import{_ as a,o as s,c as e,ag as t}from"./chunks/framework.Drp2S_UI.js";const c=JSON.parse('{"title":"T21：公共 API、示例与文档迁移记录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/public-api-migration.md","filePath":"guide/public-api-migration.md","lastUpdated":1792653875000}'),l={name:"guide/public-api-migration.md"};function n(p,i,h,r,o,d){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="t21-公共-api、示例与文档迁移记录" tabindex="-1">T21：公共 API、示例与文档迁移记录 <a class="header-anchor" href="#t21-公共-api、示例与文档迁移记录" aria-label="Permalink to &quot;T21：公共 API、示例与文档迁移记录&quot;">​</a></h1><p>当前集成入口为<a href="./font-and-esm-migration.html">字体与 ESM 迁移</a>， 英文入口为<a href="./../en/guide/font-and-esm-migration.html">Fonts and ESM migration</a>。 本记录说明 T21 的交付与验证，不替代完整 API 文档。</p><h2 id="交付" tabindex="-1">交付 <a class="header-anchor" href="#交付" aria-label="Permalink to &quot;交付&quot;">​</a></h2><ul><li>从包根公开 <code>IUpdateOption</code>，补齐 ready/create、字体注册、覆盖报告与重试接口的声明说明。 生命周期、字体描述/注册结果/元数据、覆盖报告及事件类型均可从包根消费。</li><li>主 Demo 改用 <code>await Editor.create</code>；ready 后才暴露调试实例并设置工具栏。 初始化失败会显示状态，失败实例由 create 清理。mock 明确默认自动下载与原生段落复用语义。</li><li><code>examples/esm-fonts</code> 是独立 ESM 消费工程，只导入包根 API；默认开启下载， 支持 <code>?auto=false</code> 初始关闭、运行期切换、失败状态、重试、按真实样式选择本地字体。</li><li>包消费检查从当前 tarball 独立编译、类型检查、打包该示例，无源码 alias/深路径依赖； 同时用 TypeScript 负向断言验证已删除的枚举与配置不再被导出/接受。</li><li>中英文入门、配置、实例 API、命令、监听与实验选项文档迁移到当前行为； 修正缺失的 RowFlex 导入、旧同步构造示例、默认下载未实现的过时描述， 删除旧引擎配置用法及旧增量行恢复/性能承诺。</li><li>补齐基本字体与覆盖边界、系统安装字体不等同于提供 HB 字节、字重/斜体、 Han 地区限制、失败恢复、诊断内容、ESM/WASM/Worker 部署和旧配置错误处理。</li><li>历史设计和基线保留原记录并标明历史边界，链接现行指南；不重录 T01 快照。</li></ul><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><ul><li>6 个定向 Vitest 文件、45 个用例通过：公开旧配置拒绝（构造与运行期）、 ready 生命周期、字体注册、覆盖、下载和诊断。</li><li>发行包 ESM 示例 4 项 Electron 用例通过：默认下载后覆盖恢复、关闭零请求与文件补齐、 下载失败与重试、无效文件注册的可恢复错误。字体 HTTP 使用固定本地测试数据， 不依赖实时 Bunny 网络可用性。</li><li>主 Demo 1 项 Electron 冒烟通过：就绪实例、公开命令、同步测高、工具栏缩放。</li><li>TypeScript、相关 ESLint、文档站构建、ESM 库构建、应用构建及包消费检查通过。 文档站构建同时修复了缺字文档中未转义的 cellId 占位符。</li><li>Node 22.22.1 低于项目声明的 &gt;=24.13.1，相关命令存在版本提示；构建中保留已有 WASM Node 分支外部化/分块提示。目标 Node 版本和全量/多浏览器验收留到后续阶段。</li></ul><p>运行发行包示例验证：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:package</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --serve</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 另一终端：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cypress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cypress.migration.config.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cypress/migration/public-api.cy.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --browser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> electron</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseUrl=http://127.0.0.1:4179</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p><code>package=1</code> 指定发行包预览入口，源码回归默认跳过该独立消费规格。 主 Demo 的规格使用源码服务 4318，不能对发行包预览地址执行。</p><p>T22 全量回归、T23 性能与发行资源验收、T24 最终审计仍待执行；本项没有宣称它们通过。</p>`,10)])])}const F=a(l,[["render",n]]);export{c as __pageData,F as default};
